profiling.helper_source:
package main
import (
    "encoding/json"
    "os"
    "runtime"
    "runtime/pprof"
)
func perfStats() func() {
    var start runtime.MemStats
    runtime.ReadMemStats(&start)
    f, err := os.Create(os.Getenv("GO4T_PERF_CPU_PROFILE"))
    if err != nil { panic(err) }
    if err := pprof.StartCPUProfile(f); err != nil { panic(err) }
    return func() {
        pprof.StopCPUProfile()
        if err := f.Close(); err != nil { panic(err) }
        var end runtime.MemStats
        runtime.ReadMemStats(&end)
        json.NewEncoder(os.Stderr).Encode(map[string]any{
            "mallocs": end.Mallocs-start.Mallocs,
            "allocated_bytes": end.TotalAlloc-start.TotalAlloc,
            "gc_cycles": end.NumGC-start.NumGC,
            "gc_pause_ns": end.PauseTotalNs-start.PauseTotalNs,
        })
    }
}

mutable_contract.api_source:
package mutmap

// MutMap[K, V] is an opaque IO-only handle with no class instances.
// The Ord witness is retained at creation; every observation is deferred IO.
// Insert/lookup/delete are O(log n), size is O(1), toList/freeze are O(n),
// and thaw is O(n log n). Native Int/String Ord comparisons avoid dictionaries.
// Explicit By comparators must be pure total orders and must not re-enter the
// same handle. Cancellation or panic before a write's commit leaves it unchanged;
// waiting for its mutex does not interrupt an operation already holding the lock.
extern func newBy[K, V](cmp func(K, K) Ordering) IO[MutMap[K, V]] = "go4t/rt".MutMapNew

func new[K Ord, V]() IO[MutMap[K, V]] {
  newBy(func(a, b) => compare(a, b))
}

// Each operation is atomic. A lookup followed by insert is not a transaction.
extern func insert[K Ord, V](m MutMap[K, V], k K, v V) IO[Unit] = "go4t/rt".MutMapInsert

extern func lookup[K Ord, V](m MutMap[K, V], k K) IO[Option[V]] = "go4t/rt".MutMapLookup

extern func delete[K Ord, V](m MutMap[K, V], k K) IO[Unit] = "go4t/rt".MutMapDelete

extern func size[K, V](m MutMap[K, V]) IO[Int] = "go4t/rt".MutMapSize

// Ascending snapshots never share mutable tree nodes with the handle.
extern func toList[K Ord, V](m MutMap[K, V]) IO[List[(K, V)]] = "go4t/rt".MutMapToList

extern func freeze[K Ord, V](m MutMap[K, V]) IO[Map[K, V]] = "go4t/rt".MutMapFreeze

extern func thawBy[K, V](m Map[K, V], cmp func(K, K) Ordering) IO[MutMap[K, V]] = "go4t/rt".MutMapThaw

func thaw[K Ord, V](m Map[K, V]) IO[MutMap[K, V]] {
  thawBy(m, func(a, b) => compare(a, b))
}

trial_source:
package rt

// Map and Set share immutable AVL nodes. Updates copy only the search path;
// cached heights and sizes keep lookup/update logarithmic and size constant-time.
// The distinct wrappers remain opaque to generated go4t programs.
type mapValue struct {
	root *collNode
	wide *wideNode
	// Only parsed/derived JSON objects carry source order. Ordinary Map
	// operations return a sorted map and never mutate this immutable metadata.
	jsonOrder *[]string
}
type setValue struct{ root *collNode }
type arrayValue []any

// Entries are immutable and shared by copied path nodes. Separating the two
// boxed values keeps each copied node in Go's 48-byte rather than 64-byte class.
type collEntry struct{ key, value any }

type collNode struct {
	*collEntry
	left, right  *collNode
	height, size int
}

func collHeight(n *collNode) int {
	if n == nil {
		return 0
	}
	return n.height
}

func collSize(n *collNode) int {
	if n == nil {
		return 0
	}
	return n.size
}

func collBranch(key, value any, left, right *collNode) *collNode {
	return collEntryBranch(&collEntry{key, value}, left, right)
}

func collEntryBranch(entry *collEntry, left, right *collNode) *collNode {
	return &collNode{collEntry: entry, left: left, right: right,
		height: 1 + max(collHeight(left), collHeight(right)), size: 1 + collSize(left) + collSize(right)}
}

// Balance constructs the new path nodes without ever mutating a shared child.
func collBalance(entry *collEntry, left, right *collNode) *collNode {
	if collHeight(left) > collHeight(right)+1 {
		if collHeight(left.left) >= collHeight(left.right) {
			return collEntryBranch(left.collEntry, left.left, collEntryBranch(entry, left.right, right))
		}
		middle := left.right
		return collEntryBranch(middle.collEntry,
			collEntryBranch(left.collEntry, left.left, middle.left), collEntryBranch(entry, middle.right, right))
	}
	if collHeight(right) > collHeight(left)+1 {
		if collHeight(right.right) >= collHeight(right.left) {
			return collEntryBranch(right.collEntry, collEntryBranch(entry, left, right.left), right.right)
		}
		middle := right.left
		return collEntryBranch(middle.collEntry,
			collEntryBranch(entry, left, middle.left), collEntryBranch(right.collEntry, middle.right, right.right))
	}
	return collEntryBranch(entry, left, right)
}

func collLookup(root *collNode, key any, cmp collCompare) *collNode {
	for root != nil {
		switch order := collOrder(cmp, key, root.key); {
		case order < 0:
			root = root.left
		case order > 0:
			root = root.right
		default:
			return root
		}
	}
	return nil
}

func collInsert(root *collNode, key, value any, cmp collCompare, replace bool) *collNode {
	if root == nil {
		return collBranch(key, value, nil, nil)
	}
	switch order := collOrder(cmp, key, root.key); {
	case order < 0:
		left := collInsert(root.left, key, value, cmp, replace)
		if left == root.left {
			return root
		}
		return collBalance(root.collEntry, left, root.right)
	case order > 0:
		right := collInsert(root.right, key, value, cmp, replace)
		if right == root.right {
			return root
		}
		return collBalance(root.collEntry, root.left, right)
	default:
		if !replace {
			return root
		}
		return collBranch(key, value, root.left, root.right)
	}
}

func collRemoveMin(root *collNode) (*collNode, *collNode) {
	if root.left == nil {
		return root, root.right
	}
	minimum, left := collRemoveMin(root.left)
	return minimum, collBalance(root.collEntry, left, root.right)
}

func collDelete(root *collNode, key any, cmp collCompare) *collNode {
	if root == nil {
		return nil
	}
	switch order := collOrder(cmp, key, root.key); {
	case order < 0:
		left := collDelete(root.left, key, cmp)
		if left == root.left {
			return root
		}
		return collBalance(root.collEntry, left, root.right)
	case order > 0:
		right := collDelete(root.right, key, cmp)
		if right == root.right {
			return root
		}
		return collBalance(root.collEntry, root.left, right)
	default:
		if root.left == nil {
			return root.right
		}
		if root.right == nil {
			return root.left
		}
		minimum, right := collRemoveMin(root.right)
		return collBalance(minimum.collEntry, root.left, right)
	}
}

func collWalk(root *collNode, visit func(*collNode)) {
	if root == nil {
		return
	}
	collWalk(root.left, visit)
	visit(root)
	collWalk(root.right, visit)
}

// Reverse traversal prepends directly to the generated list, avoiding an
// intermediate Go slice while producing ascending-key order.
func collList(root *collNode, rest any, value func(*collNode) any) any {
	if root == nil {
		return rest
	}
	rest = collList(root.right, rest, value)
	return collList(root.left, Shapes.Cons(value(root), rest), value)
}

func EmptyMap() any { return mapValue{} }

func MapInsert(m, key, value, compare any) any {
	root, promoted, right := wideInsert(m.(mapValue).wide, &collEntry{key, value}, collComparator(compare))
	if promoted != nil {
		root = &wideNode{count: 1, entries: [7]*collEntry{promoted}, children: [8]*wideNode{root, right}}
	}
	return mapValue{wide: root}
}

func MapLookup(m, key, compare any) any {
	if entry := wideLookup(m.(mapValue).wide, key, collComparator(compare)); entry != nil {
		return SomeOf(entry.value)
	}
	return NoneOf()
}

func MapDelete(m, key, compare any) any {
	return mapValue{root: collDelete(m.(mapValue).root, key, collComparator(compare))}
}

func MapMember(m, key, compare any) any {
	return collLookup(m.(mapValue).root, key, collComparator(compare)) != nil
}

func MapSize(m any) any { return int64(collSize(m.(mapValue).root)) }

// Duplicate keys use the last value in the input list.
func MapFromList(xs, compare any) any {
	cmp := collComparator(compare)
	var root *collNode
	for {
		pair, rest, ok := Shapes.Uncons(xs)
		if !ok {
			return mapValue{root: root}
		}
		key, value := Shapes.Untuple2(pair)
		root = collInsert(root, key, value, cmp, true)
		xs = rest
	}
}

func MapToList(m any) any {
	return wideList(m.(mapValue).wide, Shapes.Nil())
}

func MapKeys(m any) any {
	return collList(m.(mapValue).root, Shapes.Nil(), func(n *collNode) any { return n.key })
}

func MapValues(m any) any {
	return collList(m.(mapValue).root, Shapes.Nil(), func(n *collNode) any { return n.value })
}

func MapUnion(a, b, compare any) any {
	root := a.(mapValue).root
	cmp := collComparator(compare)
	collWalk(b.(mapValue).root, func(n *collNode) { root = collInsert(root, n.key, n.value, cmp, false) })
	return mapValue{root: root}
}

func collMap(root *collNode, f func(any) any) *collNode {
	if root == nil {
		return nil
	}
	left := collMap(root.left, f)
	value := f(root.value)
	right := collMap(root.right, f)
	return collBranch(root.key, value, left, right)
}

func MapMap(m, f any) any {
	return mapValue{root: collMap(m.(mapValue).root, f.(func(any) any))}
}

func MapFold(m, init, f any) any {
	fold := f.(func(any, any, any) any)
	collWalk(m.(mapValue).root, func(n *collNode) { init = fold(init, n.key, n.value) })
	return init
}

// Order-eight persistent B-tree allocation experiment.
type wideNode struct {
	entries [7]*collEntry
	children [8]*wideNode
	count int
}

func wideIndex(n *wideNode, key any, cmp collCompare) (int, bool) {
	lo, hi := 0, n.count
	for lo < hi {
		mid := (lo + hi) / 2
		switch order := collOrder(cmp, key, n.entries[mid].key); {
		case order < 0:
			hi = mid
		case order > 0:
			lo = mid + 1
		default:
			return mid, true
		}
	}
	return lo, false
}

func wideLookup(n *wideNode, key any, cmp collCompare) *collEntry {
	for n != nil {
		index, found := wideIndex(n, key, cmp)
		if found { return n.entries[index] }
		n = n.children[index]
	}
	return nil
}

func wideInsert(n *wideNode, entry *collEntry, cmp collCompare) (*wideNode, *collEntry, *wideNode) {
	if n == nil {
		return &wideNode{entries: [7]*collEntry{entry}, count: 1}, nil, nil
	}
	index, found := wideIndex(n, entry.key, cmp)
	if found {
		out := *n
		out.entries[index] = entry
		return &out, nil, nil
	}
	var left, right *wideNode
	if n.children[0] != nil {
		var promoted *collEntry
		left, promoted, right = wideInsert(n.children[index], entry, cmp)
		if promoted == nil {
			out := *n
			out.children[index] = left
			return &out, nil, nil
		}
		entry = promoted
	}
	if n.count < len(n.entries) {
		out := *n
		copy(out.entries[index+1:], n.entries[index:n.count])
		copy(out.children[index+2:], n.children[index+1:n.count+1])
		out.entries[index] = entry
		out.children[index], out.children[index+1] = left, right
		out.count++
		return &out, nil, nil
	}
	var entries [8]*collEntry
	var children [9]*wideNode
	copy(entries[:index], n.entries[:index])
	entries[index] = entry
	copy(entries[index+1:], n.entries[index:])
	copy(children[:index], n.children[:index])
	children[index], children[index+1] = left, right
	copy(children[index+2:], n.children[index+1:])
	lower, upper := &wideNode{count: 4}, &wideNode{count: 3}
	copy(lower.entries[:], entries[:4])
	copy(lower.children[:], children[:5])
	copy(upper.entries[:], entries[5:])
	copy(upper.children[:], children[5:])
	return lower, entries[4], upper
}

func wideList(n *wideNode, rest any) any {
	if n == nil { return rest }
	rest = wideList(n.children[n.count], rest)
	for i := n.count - 1; i >= 0; i-- {
		entry := n.entries[i]
		rest = Shapes.Cons(Tuple2Of(entry.key, entry.value), rest)
		rest = wideList(n.children[i], rest)
	}
	return rest
}

func EmptySet() any { return setValue{} }

func SetInsert(s, value, compare any) any {
	return setValue{collInsert(s.(setValue).root, value, nil, collComparator(compare), false)}
}

func SetDelete(s, value, compare any) any {
	return setValue{collDelete(s.(setValue).root, value, collComparator(compare))}
}

func SetMember(s, value, compare any) any {
	return collLookup(s.(setValue).root, value, collComparator(compare)) != nil
}

func SetSize(s any) any { return int64(collSize(s.(setValue).root)) }

func SetFromList(xs, compare any) any {
	cmp := collComparator(compare)
	var root *collNode
	for {
		x, rest, ok := Shapes.Uncons(xs)
		if !ok {
			return setValue{root}
		}
		root = collInsert(root, x, nil, cmp, false)
		xs = rest
	}
}

func SetToList(s any) any {
	return collList(s.(setValue).root, Shapes.Nil(), func(n *collNode) any { return n.key })
}

func SetUnion(a, b, compare any) any {
	root := a.(setValue).root
	cmp := collComparator(compare)
	collWalk(b.(setValue).root, func(n *collNode) { root = collInsert(root, n.key, nil, cmp, false) })
	return setValue{root}
}

func SetIntersection(a, b, compare any) any {
	root, other := a.(setValue).root, b.(setValue).root
	if other == nil {
		return EmptySet()
	}
	cmp := collComparator(compare)
	collWalk(a.(setValue).root, func(n *collNode) {
		if collLookup(other, n.key, cmp) == nil {
			root = collDelete(root, n.key, cmp)
		}
	})
	return setValue{root}
}

func SetDifference(a, b, compare any) any {
	root := a.(setValue).root
	cmp := collComparator(compare)
	collWalk(b.(setValue).root, func(n *collNode) { root = collDelete(root, n.key, cmp) })
	return setValue{root}
}

func ArrayFromList(xs any) any {
	var values arrayValue
	for {
		x, rest, ok := Shapes.Uncons(xs)
		if !ok {
			return values
		}
		values = append(values, x)
		xs = rest
	}
}

func ArrayToList(a any) any {
	values := a.(arrayValue)
	xs := Shapes.Nil()
	for i := len(values) - 1; i >= 0; i-- {
		xs = Shapes.Cons(values[i], xs)
	}
	return xs
}

func ArrayLength(a any) any { return int64(len(a.(arrayValue))) }

func ArrayGet(a, index any) any {
	values, i := a.(arrayValue), index.(int64)
	if i < 0 || i >= int64(len(values)) {
		return NoneOf()
	}
	return SomeOf(values[i])
}

func ArraySet(a, index, value any) any {
	values, i := a.(arrayValue), index.(int64)
	if i < 0 || i >= int64(len(values)) {
		return a
	}
	result := make(arrayValue, len(values))
	copy(result, values)
	result[i] = value
	return result
}

func ArrayMap(a, f any) any {
	values, apply := a.(arrayValue), f.(func(any) any)
	result := make(arrayValue, len(values))
	for i, value := range values {
		result[i] = apply(value)
	}
	return result
}

func ArrayFold(a, init, f any) any {
	fold := f.(func(any, any) any)
	for _, value := range a.(arrayValue) {
		init = fold(init, value)
	}
	return init
}

func ArrayPush(a, value any) any {
	values := a.(arrayValue)
	result := make(arrayValue, len(values)+1)
	copy(result, values)
	result[len(values)] = value
	return result
}

// Slice is half-open, with both bounds clamped to [0, length]. A reversed
// interval is empty. Sharing the storage is safe because every write copies.
func ArraySlice(a, start, end any) any {
	values := a.(arrayValue)
	n := int64(len(values))
	lo, hi := min(max(start.(int64), 0), n), min(max(end.(int64), 0), n)
	if hi <= lo {
		return arrayValue(nil)
	}
	return values[lo:hi:hi]
}

func ArraySortBy(a, compare any) any {
	return arraySortBy(a, compare)
}
